
-- =====================================================
-- PROJECT: Customer Churn & Retention Intelligence
-- PHASE 6: Customer Lifetime Value & Revenue Risk
-- STEP 35: Revenue Concentration Analysis
-- PURPOSE:
-- Measure how much total revenue is generated by
-- the top 1%, 5% and 10% highest-revenue customers.
-- =====================================================

-- STEP 1: Calculate lifetime revenue for each customer
WITH customer_lifetime_revenue AS (

    SELECT
        c.customer_unique_id,

        SUM(oi.price) AS lifetime_revenue

    FROM olist.customers c

    INNER JOIN olist.orders o
        ON c.customer_id = o.customer_id

    INNER JOIN olist.order_items oi
        ON o.order_id = oi.order_id

    WHERE o.order_status = 'delivered'

    GROUP BY c.customer_unique_id
),

-- STEP 2: Rank customers by lifetime revenue
ranked_customers AS (

    SELECT
        customer_unique_id,
        lifetime_revenue,

        ROW_NUMBER() OVER (
            ORDER BY lifetime_revenue DESC, customer_unique_id
        ) AS revenue_rank,

        COUNT(*) OVER () AS total_customers

    FROM customer_lifetime_revenue
),

-- STEP 3: Calculate total business revenue
overall_revenue AS (

    SELECT
        SUM(lifetime_revenue) AS total_revenue,
        COUNT(*) AS total_customers

    FROM customer_lifetime_revenue
),

-- STEP 4: Define top customer groups
top_customer_groups AS (

    SELECT
        'Top 1%' AS customer_group,
        CEIL(total_customers * 0.01) AS selected_customer_count
    FROM overall_revenue

    UNION ALL

    SELECT
        'Top 5%',
        CEIL(total_customers * 0.05)
    FROM overall_revenue

    UNION ALL

    SELECT
        'Top 10%',
        CEIL(total_customers * 0.10)
    FROM overall_revenue
),

-- STEP 5: Calculate revenue generated by each group
concentration_summary AS (

    SELECT
        tg.customer_group,

        tg.selected_customer_count AS total_customers,

        SUM(rc.lifetime_revenue) AS group_revenue,

        AVG(rc.lifetime_revenue) AS avg_customer_revenue

    FROM top_customer_groups tg

    INNER JOIN ranked_customers rc
        ON rc.revenue_rank <= tg.selected_customer_count

    GROUP BY
        tg.customer_group,
        tg.selected_customer_count
)

-- STEP 6: Display revenue concentration metrics
SELECT
    cs.customer_group,

    cs.total_customers,

    ROUND(cs.group_revenue, 2) AS total_revenue,

    ROUND(
        cs.group_revenue * 100.0 / ov.total_revenue,
        2
    ) AS revenue_contribution_pct,

    ROUND(cs.avg_customer_revenue, 2)
        AS avg_customer_revenue

FROM concentration_summary cs

CROSS JOIN overall_revenue ov

ORDER BY
    CASE cs.customer_group
        WHEN 'Top 1%' THEN 1
        WHEN 'Top 5%' THEN 2
        WHEN 'Top 10%' THEN 3
    END;
